'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided-base-reinterpret-complex64' );


// MAIN //

/**
* Returns the index of the first falsy element in a single-precision complex floating-point strided array using alternative indexing semantics.
*
* ## Notes
*
* -   A complex number is falsy when both its real and imaginary components are falsy.
* -   If unable to find a falsy element, the function returns `-1`.
* -   The function explicitly treats `NaN` values as falsy.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex64Array} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {integer} index
*
* @example
* var Complex64Array = require( '@stdlib/array-complex64' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 4.0, 5.0 ] );
*
* var idx = cindexOfFalsy( x.length, x, 1, 0 );
* // returns 1
*/
function cindexOfFalsy( N, x, strideX, offsetX ) {
	var view;
	var ix;
	var i;

	if ( N <= 0 ) {
		return -1;
	}

	// Reinterpret the complex input array as a real-valued array of interleaved real and imaginary components:
	view = reinterpret( x, 0 );

	// Adjust the stride and offset to account for the interleaved storage:
	ix = offsetX * 2;
	strideX *= 2;

	for ( i = 0; i < N; i++ ) {
		if ( !view[ ix ] && !view[ ix+1 ] ) {
			return i;
		}
		ix += strideX;
	}
	return -1;
}


// EXPORTS //

module.exports = cindexOfFalsy;
